INSERT OR IGNORE INTO sections (key, data, updated_at) VALUES ('site', '{"title":"Kiyas Mahmud · AI Researcher","description":"Computer Science undergraduate at AIUB researching autonomous web agents, multimodal learning, and trustworthy AI. Papers accepted at IEEE TENCON 2026 and ICECCME 2026.","ogImage":"/images/og/kiyas-mahmud.jpg?v=3","cvUrl":"/pdf/kiyasmahmud.pdf","cvFileName":"Kiyas-Mahmud.pdf","footerRole":"AI Researcher · Computer Science, AIUB"}', 1795371077186);
INSERT OR IGNORE INTO sections (key, data, updated_at) VALUES ('hero', '{"eyebrow":"Dhaka, Bangladesh · Open to graduate research positions","name":"Kiyas Mahmud","role":"AI Researcher · Autonomous Agents & Multimodal Learning","lede":"Computer Science undergraduate at American International University-Bangladesh (AIUB). My thesis, WebFARM, studies how autonomous web agents detect failures, recover from them, and remember what went wrong. I have contributed to papers accepted at IEEE TENCON 2026 and ICECCME 2026.","portrait":"/images/profile/kiyas-portrait.jpg","portraitAlt":"Kiyas Mahmud in a grey suit","portraitCaption":"BSc CS · AIUB · Class of 2026","scholar":"https://scholar.google.com/citations?user=nWZ3Gr0AAAAJ&hl=en&authuser=1","github":"https://github.com/Kiyas-Mahmud","linkedin":"https://www.linkedin.com/in/kiyas-mahmud-a043b8256/","email":"kiyasmahmud@gmail.com","stats":[{"label":"Publications","value":"4","suffix":"","note":"2 accepted at 2026 conferences"},{"label":"CGPA","value":"3.45","suffix":"/4.00","note":"BSc Computer Science, AIUB"},{"label":"National award","value":"Winner","suffix":"","note":"Bangladesh ICT & Innovation Awards 2025"},{"label":"Thesis dataset","value":"40K","suffix":"","note":"real-browser interaction steps"}]}', 1795371077186);
INSERT OR IGNORE INTO sections (key, data, updated_at) VALUES ('about', '{"heading":"Profile & education","lead":"I work where machine learning research meets software that has to run in the real world.","body":"My research covers autonomous AI agents, multimodal learning, and explainable, trustworthy AI. Alongside it, I have led industry projects end to end, from a 540-endpoint field-sales platform for Elite Group of Industries to a multi-tenant point-of-sale system for a mobile phone wholesaler. Building systems that real users depend on shapes how I design experiments: measurable, reproducible, and honest about failure.","interests":["Autonomous AI Agents","Multimodal Learning","Vision-Language Models","Trustworthy AI","Explainable AI","Machine Learning","Cloud Optimization"],"education":[{"degree":"BSc in Computer Science","year":"Dec 2026","school":"American International University-Bangladesh (AIUB), Dhaka","score":"CGPA 3.45 / 4.00"},{"degree":"Higher Secondary Certificate, Science","year":"2021","school":"Ideal College, Dhanmondi, Dhaka","score":"GPA 4.75 / 5.00"},{"degree":"Secondary School Certificate, Science","year":"2018","school":"Singair Pilot Government High School, Manikganj","score":"GPA 4.94 / 5.00"}],"languages":"English · fluent  |  Bangla · native"}', 1795371077186);
INSERT OR IGNORE INTO sections (key, data, updated_at) VALUES ('research', '{"heading":"Research experience","thesisTag":"Undergraduate thesis · Lead technical researcher","thesisTitle":"WebFARM: A Multimodal Framework for Failure Detection, Adaptive Recovery and Episodic Memory in Autonomous Web Agents","thesisSupervisor":"Supervisor: Asst. Prof. Nuzhat Tabassum, Department of Computer Science, AIUB","thesisPoints":["Led the technical research: methodology and experimental design, framework architecture and implementation, model integration, experiment execution, and results analysis.","Developed and evaluated multimodal approaches using Qwen2-VL-2B, Qwen2.5-VL-7B, and InternVL3.5-8B on Web-Gold-40K, a dataset of 40,017 real-browser interaction steps.","Evaluated Browser Use and SeeAct agents across 22 websites and 42 tasks."],"metrics":[{"label":"Best F1","value":"0.839","unit":""},{"label":"Recovery prediction","value":"93.49%","unit":""},{"label":"Browser Use gain","value":"+13.1","unit":"pp"},{"label":"SeeAct gain","value":"+20.2","unit":"pp"}],"metricsNote":"Preliminary results; task-completion gains measured over the unmodified agents.","links":[{"type":"github","label":"Code","url":"https://github.com/Kiyas-Mahmud/webagent"},{"type":"dataset","label":"Web-Gold-40K dataset","url":"https://github.com/Kiyas-Mahmud/multimodal-browser-agent-data"}],"roles":[{"period":"Jan 2025 – Mar 2026","title":"Research Assistant · Tech Wing''s Lab, Dhaka","text":"Assisted with research planning, analysis, documentation, and research paper preparation; reviewed academic papers and guided junior researchers in academic writing and research methods."}]}', 1795371077186);
INSERT OR IGNORE INTO sections (key, data, updated_at) VALUES ('publications', '{"heading":"Publications","items":[{"title":"AutoTuneX: An Intelligent Self-Optimizing Runtime Framework for Cloud Applications","status":"accepted","venue":"IEEE TENCON 2026, Bali, Indonesia","note":"Five-component closed-loop Kubernetes autoscaler. Live Minikube experiments reported 72.2% lower cost, zero SLO violations, and zero scaling oscillations using Linear Regression.","links":[{"type":"github","label":"Code","url":"https://github.com/Kiyas-Mahmud/AutoTuneX"}]},{"title":"Hybrid FraudShield: Detecting Financial Fraud in Real Time with Explainable AI","status":"accepted","venue":"ICECCME 2026, Bali, Indonesia","note":"Stacking ensemble with a Logistic Regression meta-learner on about 590,000 IEEE-CIS transactions: 98.7% accuracy, 0.978 ROC-AUC, and an 8.1-point precision gain over XGBoost at equal recall, with SHAP explanations under 500 ms.","links":[{"type":"github","label":"Code","url":"https://github.com/Kiyas-Mahmud/Hybrid-Fraud-Shield"}]},{"title":"Comparative Analysis of Heap Algorithms for Anomaly Localization in Dynamic Graph Neural Networks","status":"published","venue":"Atlantis Press, Proceedings of ICERIE 2025 · online 18 Nov 2025","note":"Compared Fibonacci, D-ary, and PriorityQueue heaps in Dijkstra''s Algorithm for anomaly localization, examining efficiency, memory use, and scalability.","links":[{"type":"scholar","label":"Google Scholar","url":"https://scholar.google.com/citations?user=nWZ3Gr0AAAAJ&hl=en&authuser=1"}]},{"title":"Real-Time Fusion of Behavioral and Transactional Data for Fraud Detection","status":"presented","venue":"ICASF 2025, Dubai","note":"Ensemble framework combining behavioral, transactional, and device-level data for real-time fraud detection.","links":[]}]}', 1795371077186);
INSERT OR IGNORE INTO sections (key, data, updated_at) VALUES ('experience', '{"heading":"Professional & industry experience","items":[{"tag":"Industry collaboration","title":"Sales Officer Copilot","org":"Elite Group of Industries, Bangladesh","kind":"AI-powered sales management platform","private":true,"points":["Led the development of a Bangla and English sales app with GPS tracking, reporting, and live team monitoring.","Built a secure backend with 540 API endpoints and integrated a Gemini-powered AI sales assistant."],"tech":["Python","FastAPI","Cloudflare Workers","Flutter","React","Gemini API"]},{"tag":"Client project · 2026","title":"Phonelot","org":"Taslima Enterprise, Bangladesh","kind":"Wholesale mobile phone POS","private":true,"points":["Developed a Bangla and English sales system for phone inventory, orders, payments, and barcode scanning.","Built a secure backend with inventory tracking, activity logs, backups, and 494 automated tests."],"tech":["Nuxt 4","TypeScript","Hono","Cloudflare D1","Tesseract.js","ZXing WASM"]}]}', 1795371077186);
INSERT OR IGNORE INTO sections (key, data, updated_at) VALUES ('projects', '{"heading":"Selected projects","moreUrl":"https://github.com/Kiyas-Mahmud?tab=repositories","items":[{"badge":"WICEBD Silver Medal","title":"ScholarNest","tagline":"AI-powered scholarship management platform","points":["Global scholarship discovery, application tracking, professor CRM, AI-personalized emails, and document review.","Automated follow-ups, deadline alerts, analytics, risk scoring, and secure document management."],"tech":["Nuxt 3","Vue.js","TypeScript","PostgreSQL","Prisma ORM","Redis","Gemini AI"],"liveUrl":"https://scholarnest.app","gitUrl":"","private":false},{"badge":"National ICT Award 2025 · APICTA 2025","title":"Hybrid Fraud Shield","tagline":"Explainable AI-based fraud detection","points":["Hybrid ML/DL system combining XGBoost, CatBoost, CNN, and BiLSTM with ensemble learning for real-time transaction risk assessment.","SHAP and Integrated Gradients for explainable predictions, served through a FastAPI real-time inference service."],"tech":["Python","Scikit-learn","XGBoost","CatBoost","SHAP","FastAPI"],"liveUrl":"","gitUrl":"https://github.com/Kiyas-Mahmud/Hybrid-Fraud-Shield","private":false},{"badge":"","title":"HandyLaw","tagline":"AI-powered legal drafting platform","points":["AI-assisted Bangla legal drafting with verified legal-source citations, structured case analysis, and mandatory advocate review and approval.","Secure AI authorization, Gemini output validation, sandboxed DOCX/PDF generation, and 2,400+ automated tests."],"tech":["TypeScript","Hono","Cloudflare Workers","D1","Nuxt 4","Gemini API","Zod","Vitest"],"liveUrl":"","gitUrl":"","private":true}]}', 1795371077186);
INSERT OR IGNORE INTO sections (key, data, updated_at) VALUES ('skills', '{"heading":"Technical skills","items":[{"label":"AI / ML","value":"Scikit-learn, XGBoost, CatBoost, SHAP/TreeSHAP, Gemini API, model evaluation, preprocessing, ensemble and stacking methods, fraud detection"},{"label":"Agentic systems","value":"Autonomous web agents, failure detection, adaptive recovery, episodic memory, AI agent integration"},{"label":"Programming","value":"Python, C++, JavaScript, TypeScript, PHP, C#, Dart"},{"label":"Frameworks & cloud","value":"FastAPI, Flutter, React, Next.js, Vue, Nuxt 3/4, Laravel, Hono, SQLAlchemy, Drizzle ORM, Zod, PWA, Cloudflare Workers/D1/R2/Queues/Vectorize/AI Gateway, Docker"},{"label":"Data, security & tools","value":"PostgreSQL, MySQL, SQL Server, Redis, RBAC, biometric authorization, audit logging, Tesseract.js, Vitest, GitHub Actions, Git, Jupyter, Pandas, NumPy, Supervisely"}]}', 1795371077186);
INSERT OR IGNORE INTO sections (key, data, updated_at) VALUES ('honors', '{"heading":"Honors, awards & certificates","awards":[{"icon":"trophy","title":"Winner · Bangladesh ICT & Innovation Awards 2025","note":"National recognition for Hybrid Fraud Shield"},{"icon":"medal","title":"Silver Medal · World Invention Competition & Exhibition Bangladesh (WICEBD)","note":"Awarded for ScholarNest"},{"icon":"globe","title":"Participant · Asia Pacific ICT Alliance (APICTA) Awards 2025","note":"Presented Hybrid Fraud Shield in the regional round"}],"courses":[{"title":"Machine Learning with Python","issuer":"IBM · Coursera"},{"title":"PHP and Laravel, Batch 2","issuer":"OSTAD"}],"certificates":[{"image":"/images/Certificate/web/WICE2026.webp","alt":"WICEBD 2026 silver medal certificate"},{"image":"/images/Certificate/web/APICTA.webp","alt":"APICTA Awards certificate"},{"image":"/images/Certificate/web/BIIN.webp","alt":"BIIN recognition certificate"},{"image":"/images/Certificate/web/BuildFest2026.webp","alt":"BuildFest 2026 certificate"},{"image":"/images/Certificate/web/Daffodil.webp","alt":"Daffodil International University certificate"},{"image":"/images/Certificate/web/Conference.webp","alt":"Conference publication certificate"},{"image":"/images/Certificate/web/SUST.webp","alt":"SUST recognition certificate"}]}', 1795371077186);
INSERT OR IGNORE INTO sections (key, data, updated_at) VALUES ('leadership', '{"heading":"Leadership & community","items":[{"role":"Founder & Instructor","org":"CodeSage","text":"Founded an independent educational platform and taught programming and technology courses to over 100 university students, with technical mentorship and practical coding guidance."},{"role":"Finance Head","org":"Charity For Happiness","text":"Managed financial activities and supported charitable work: financial assistance, food and winter clothing distribution, and direct on-field support for underprivileged communities."},{"role":"Patrol Leader (Mate) · 2018","org":"6th National COMDECA · Bangladesh Scouts","text":"Led a Scout patrol at the National Community Development Camp in Haimchar, Chandpur, coordinating team logistics, disaster preparedness drills, and community service."},{"role":"Sixer (Team Leader) · 2007","org":"Manikganj District Cub Camporee · Bangladesh Scouts","text":"Led a six-member Cub Scout unit representing Singair Pilot Primary School, coordinating camp logistics, team drills, and community service."}]}', 1795371077186);
