INSERT OR IGNORE INTO sections (key, data, updated_at) VALUES ('contact', '{"heading":"Get in touch","lede":"I am looking for graduate research opportunities in autonomous agents, multimodal learning, and trustworthy AI. I would be glad to hear from faculty, labs, and scholarship committees.","email":"kiyasmahmud@gmail.com","phone":"+880 1609 785885","location":"Mirpur-1, Dhaka, Bangladesh","references":[{"name":"Prof. Dr. Afroza Nahar","title":"Professor, Department of Computer Science, AIUB"},{"name":"Asst. Prof. Nuzhat Tabassum","title":"Assistant Professor, Department of Computer Science, AIUB · Undergraduate thesis supervisor"}],"refsNote":"Contact details for referees are in the CV."}', 1795371077186);
